/**
 * Figures for the statistical-distributions guide.
 *
 * Every histogram here is the real thing: 20 000 values generated by the CLI
 * with the exact attributes printed on the figure, then counted. Nothing is
 * sketched from what a textbook says the shape ought to look like.
 *
 * Language-free by the rule in figure-kit.mjs — the only words inside are
 * attribute spellings, which are code.
 *
 * Run:  node webdoc/scripts/make-distribution-figures.mjs
 */

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { C, box, histogram, makeRunner, oneColumn, svg, text } from './figure-kit.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..', '..');
const OUT = join(HERE, '..', 'static', 'img', 'distributions');
const run = makeRunner(join(ROOT, 'typescript', 'dist', 'cli', 'main.js'), 'distributions');

mkdirSync(OUT, { recursive: true });

const N = 20000;
const values = (attrs, count = N) =>
  run(oneColumn(`<gen type="number" ${attrs}/>`, count, 'doc')).map(Number);

const W = 680;
const PAD_L = 30;
const PAD_R = 26;
const TOP = 16;

/**
 * One histogram panel.
 *
 * The horizontal range stops at the 99th percentile: a heavy tail (pareto, zipf)
 * otherwise squeezes every visible value into the first bar, and a shape you
 * cannot see teaches nothing. The page text says so next to the figure.
 *
 * `label` is the generator's own attributes — code, so it stays in the picture;
 * the axis carries a few round numbers and nothing else. The first and last tick
 * labels are anchored INSIDE the panel, or they collide with the neighbour.
 */
function panel(b, vals, label, { buckets = 34, color = C.made, ticks = 4, clip = 0.99 } = {}) {
  const sorted = [...vals].sort((a, z) => a - z);
  const lo = sorted[0];
  const hi = sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * clip))];
  const shown = sorted.filter((v) => v <= hi);
  const span = hi - lo || 1;
  // Integer data needs whole-number bucket widths, or some buckets catch one more
  // value than their neighbours and the histogram grows a comb of false spikes.
  let hiForBuckets = hi;
  if (shown.every(Number.isInteger)) {
    const width = Math.max(1, Math.round((span + 1) / buckets));
    buckets = Math.ceil((span + 1) / width);
    hiForBuckets = lo + buckets * width;
  }
  const axis = [];
  for (let i = 0; i <= ticks; i++) {
    const v = lo + (span * i) / ticks;
    const x = b.sx(i / ticks);
    const anchor = i === 0 ? 'start' : i === ticks ? 'end' : 'middle';
    axis.push(
      `<line x1="${x.toFixed(1)}" y1="${b.y + b.h}" x2="${x.toFixed(1)}" y2="${b.y + b.h + 4}" stroke="${C.axis}" opacity="0.55"/>`,
      text(x, b.y + b.h + 16, formatTick(v, span), { anchor, size: 10.5 }),
    );
  }
  return [
    histogram(b, shown, { buckets, lo, hi: hiForBuckets, color }),
    `<line x1="${b.x}" y1="${b.y + b.h}" x2="${b.x + b.w}" y2="${b.y + b.h}" stroke="${C.axis}" stroke-width="1" opacity="0.55"/>`,
    ...axis,
    text(b.x + b.w / 2, b.y + b.h + 34, label, { anchor: 'middle', size: 11.5 }),
  ].join('\n');
}

function formatTick(v, span) {
  if (span >= 5000) return `${Math.round(v / 1000)}k`;
  if (span >= 1000) return String(Math.round(v / 100) * 100);
  if (span >= 20) return String(Math.round(v));
  if (span >= 2) return v.toFixed(1);
  return v.toFixed(2);
}

const FIGURES = {};

/** Uniform versus normal over the same range — the "why bother" figure. */
FIGURES['uniform-vs-normal'] = () => {
  const panels = [
    { vals: values('value="150..200"'), label: 'value="150..200"', color: C.faint },
    { vals: values('distribution="normal" mean="175" sd="8"'), label: 'distribution="normal"' },
  ].map((p, i) => panel(box(PAD_L + i * 330, TOP, 300, 150), p.vals, p.label, { color: p.color }));
  return svg(W, 220, panels.join('\n'));
};

/** The nine shapes, three to a row, each from its own run. */
const NINE = [
  ['normal', 'distribution="normal" mean="170" sd="10"'],
  ['lognormal', 'distribution="lognormal" meanlog="10.8" sdlog="0.5"'],
  ['exponential', 'distribution="exponential" rate="0.5" decimals="2"'],
  ['pareto', 'distribution="pareto" alpha="1.5" xmin="1000"'],
  ['weibull', 'distribution="weibull" shape="2" scale="1000"'],
  ['poisson', 'distribution="poisson" lambda="4"'],
  ['zipf', 'distribution="zipf" n="30" s="1.1"'],
  ['gamma', 'distribution="gamma" shape="3" scale="2" decimals="2"'],
  ['beta', 'distribution="beta" alpha="2" beta="5" decimals="3"'],
];

FIGURES['nine-shapes'] = () => {
  const cols = 3;
  const cw = 206;
  const ch = 108;
  const panels = NINE.map(([name, attrs], i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const b = box(PAD_L + col * (cw + 12), TOP + row * (ch + 56), cw, ch);
    // The distribution's own name is its identifier in the config — code, not prose.
    return panel(b, values(attrs, 8000), `"${name}"`, { buckets: 26, ticks: 2 });
  });
  return svg(W, TOP + 3 * (ch + 56) + 6, panels.join('\n'));
};

/** Clipping: the same bell, then bounded — the tail piles up on the bound. */
FIGURES['min-max'] = () => {
  const panels = [
    { vals: values('distribution="normal" mean="170" sd="10"'), label: 'distribution="normal"' },
    {
      vals: values('distribution="normal" mean="170" sd="10" min="160" max="180"'),
      label: 'min="160" max="180"',
    },
  ].map((p, i) => panel(box(PAD_L + i * 330, TOP, 300, 150), p.vals, p.label));
  return svg(W, 220, panels.join('\n'));
};

for (const [name, build] of Object.entries(FIGURES)) {
  writeFileSync(join(OUT, `${name}.svg`), build());
}

console.log(`distributions: ${Object.keys(FIGURES).length} language-free figures → ${OUT}`);
